def solve():
    # Let's test if r=2/3 is a solution for a small set S
    # If S is a set of 100 numbers, P1 is the set of differences.
    # P2 = {3 * p * q * r | p, q in P1}
    # P3 = {x^2 + y^2 - z^2 - w^2 | x, y, z, w in P1}
    # We want to check if P2 is a subset of P3.

    import itertools

    def check_r(r, S):
        P1 = set()
        for f in S:
            for g in S:
                P1.add(f - g)

        P2 = set()
        for p in P1:
            for q in P1:
                P2.add(3 * p * q * r)

        # P3 is the set of all x^2 + y^2 - z^2 - w^2 for x, y, z, w in P1.
        # To check if P2 is a subset of P3, we can check each element of P2.
        for val in P2:
            # Check if val = x^2 + y^2 - z^2 - w^2 for some x, y, z, w in P1.
            # This is equivalent to val = x^2 + y^2 - (z^2 + w^2)
            # Let squares = {x^2 for x in P1}
            squares = [x*x for x in P1]
            found = False
            for x2 in squares:
                for y2 in squares:
                    for z2 in squares:
                        for w2 in squares:
                            if x2 + y2 - z2 - w2 == val:
                                found = True
                                break
                        if found: break
                    if found: break
                if found: break
            if not found:
                return False
        return True

    # Test r = 2/3 with a small set S
    S1 = [1, 2, 3, 4, 5]
    print(f"r=2/3, S={S1}: {check_r(2/3, S1)}")

    # Test r = 0
    print(f"r=0, S={S1}: {check_r(0, S1)}")

    # Test r = 1/3
    print(f"r=1/3, S={S1}: {check_r(1/3, S1)}")

    # Test r = 1
    print(f"r=1, S={S1}: {check_r(1, S1)}")

