def check_r_improved(r, S):
    P1 = set()
    for f in S:
        for g in S:
            P1.add(f - g)

    P2 = set()
    for p in P1:
        for q in P1:
            P2.add(3 * p * q * r)

    squares = [x*x for x in P1]

    for val in P2:
        found = False
        for x2 in squares:
            for y2 in squares:
                # val = x2 + y2 - (z2 + w2)
                # z2 + w2 = x2 + y2 - val
                target = x2 + y2 - val
                # Check if target is a sum of two squares from squares
                for z2 in squares:
                    w2 = target - z2
                    if w2 in squares:
                        found = True
                        break
                if found: break
            if found: break
        if not found:
            return False
    return True

